{
  "name": "opencode-log-plugin",
  "version": "0.3.0",
  "description": "Observability collector plugin for OpenCode agents. One-way outbound event shipping to opencode-log-viewer (https://github.com/Mercuron/opencode-log-viewer).",
  "type": "module",
  "license": "MIT",
  "author": "Mercuron",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Mercuron/opencode-log-plugin.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "observability",
    "logging",
    "tracing"
  ],
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "pretest": "tsc -p tsconfig.test.json",
    "test": "node --test dist-test/*.test.js",
    "prepublishOnly": "npm run typecheck && npm test && npm run build"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.18.16"
  },
  "devDependencies": {
    "@types/node": "^22.0.0",
    "typescript": "^5.8.2"
  }
}
